class File:
    def __init__(self, path):
        self.path = path

    def isFolder(self):
        return False

    def getExtension(self):
        return self.path.split('.')[-1]


class Folder:
    def __init__(self, name, items):
        self.name = name
        self.items = items

    def isFolder(self):
        return True

    def getItems(self):
        return self.items


